import sen0401_ch08_sources_v1_0_0 as S

PUBS = [(s["id"], s["label"], s["url"], bool(s.get("primary"))) for s in S.SRC]

SECTIONS = ("Digital Signatures", "How Digital Signatures Work", "Creating a Digital Signature", "Verifying the Signature", "Signature Hash Types (SIGHASH)", "Schnorr Signatures",
            "Serialization of Schnorr Signatures", "Schnorr-based Scriptless Multisignatures", "Schnorr-based Scriptless Threshold Signatures", "ECDSA Signatures", "ECDSA Algorithm",
            "Serialization of ECDSA Signatures (DER)", "The Importance of Randomness in Signatures", "Segregated Witness's New Signing Algorithm")
CONCEPTS = [("Section", x) for x in SECTIONS] + [("Concept", x) for x in (
    "digital signature", "signature hash", "SIGHASH_ALL", "SIGHASH_NONE", "SIGHASH_SINGLE", "SIGHASH_ANYONECANPAY", "BIP118", "discrete logarithm problem", "nonce", "challenge",
    "Fiat-Shamir transform", "BIP340", "x-only public key", "linearity", "batch verification", "key prefixing", "scriptless multisignature", "key cancellation attack", "MuSig2",
    "Shamir secret sharing", "scriptless threshold signature", "ECDSA", "R and s", "malleability", "DER", "low-S rule", "RFC 6979", "nonce reuse", "BIP143", "O(n) hashing",
    "taproot signature", "SIGHASH_DEFAULT")]

A, WU, NI, W15, LW, DT, CH, BC = ("Antonopoulos and Harding, 2023", "Wuille et al., 2020", "Nick et al., 2022", "Wuille, 2015", "Lau and Wuille, 2016", "Decker and Towns, 2017",
                                 "Chow, 2024", "Bitcoin Core, 2026")
FINDINGS = [
 ("F1", "Background", "Chapter 8 of the 3rd edition explains what a digital signature is for in Bitcoin, how a signature commits to a chosen part of a transaction through the SIGHASH flag, how the schnorr algorithm works and what it makes possible (multisignatures and threshold signatures that look like one signature), how ECDSA, the signature Bitcoin used until 2021, works and is serialized, why the random nonce must never repeat, and how segwit changed what is hashed; this package recomputes its figures and examples and checks the statements that moved since print (%s)." % A, ["P01"]),
 ("F2", "Comparative analysis", "The book says that the arithmetic of the schnorr and ECDSA equations is performed modulo p, the prime of the field; the scalars of the signature equations (the nonce, the challenge, the private key and the value s) are instead reduced modulo n, the order of the group of points, which is a different number: the equation sG = kG + eX holds when s is reduced modulo n and fails when it is reduced modulo p, and BIP340 and SEC 2 give both numbers separately (%s) (%s) (SECG, 2010)." % (A, WU), ["P01", "P03", "P36"]),
 ("F3", "Comparative analysis", "The book's table of SIGHASH flags says SINGLE signs 'the one output with the same index number as the signed input', but not what happens when there is no such output: in the legacy signature hash the function returns the number one instead of a hash, which is the SIGHASH_SINGLE bug that Bitcoin Core's source marks and that the Bitcoin Wiki describes, and Bitcoin Core 31.1 refuses to sign such an input, leaving it unsigned with an error, while it signs the same transaction when each input has an output (%s) (%s)." % (BC, "Bitcoin Wiki, 2026"), ["P20", "P24", "P50"]),
 ("F4", "Comparative analysis", "The book's table says ALL, NONE and SINGLE sign 'all inputs', which is true of the outpoints (which coins are spent) but not of the other inputs' sequence numbers: the executed probe shows that, as BIP143 specifies for segwit version 0 and the legacy algorithm does too, the sequence numbers of other inputs are left out of the hash under NONE and SINGLE as well as under ANYONECANPAY (%s)." % LW, ["P01", "P09", "P20"]),
 ("F5", "Comparative analysis", "The book's segwit section describes only the quadratic hashing and its O(n) repair; it does not say what else BIP143 changed, and it carries an unfinished editor's note about values: BIP143 makes every segwit version 0 signature commit to the amount of the coin being spent, which the legacy hash never does, and BIP341 goes further and commits to the amounts and scripts of all inputs unless ANYONECANPAY is used, which is what lets a hardware wallet check the fee without seeing the previous transactions (%s) (%s)." % (LW, WU), ["P01", "P05", "P09"]),
 ("F6", "Comparative analysis", "The 72-byte signature printed in the book's DER section is a real mainnet signature from block 277,316 (27 December 2013); it verifies against the transaction's legacy signature hash, and it is long because its R value begins with the byte 0x88 and so needs a padding zero, whereas Bitcoin Core grinds the nonce until R is small, and the 300 signatures that Core 31.1 made in one transaction are all 70 or 71 bytes (298 of 71 and 2 of 70, with the hash type byte) and all low-R (%s) (%s)." % (A, BC), ["P01", "P23", "P65"]),
 ("F7", "Contemporary developments", "Bitcoin Core derives the ECDSA nonce with the deterministic function of RFC 6979 and grinds it for a small R, and it signs a taproot input with an all-zero auxiliary random value for now, so that signing the same transaction twice gives the same signature in both cases, which the regtest run confirms; the book says only that BIP340 and RFC 6979 can be deterministic (%s) (%s)." % (BC, "Pornin, 2013"), ["P23", "P24", "P34"]),
 ("F8", "Comparative analysis", "The book does not separate the signature rules that are consensus from those that are only policy: Bitcoin Core accepts a transaction with a high-S signature in a block (the rule of BIP146 is policy, so nodes do not relay it) while a signature that is not strictly DER encoded makes the block invalid (a consensus rule since BIP66 and the July 2015 soft fork), as the regtest run shows by mining both (%s) (%s)." % (LW, W15), ["P08", "P10", "P20"]),
 ("F9", "Comparative analysis", "The book says the 65-byte taproot signature carries an explicit hash type; BIP341 makes the explicit value 0x00 invalid (the default is the absence of the byte), so the only valid explicit values are 0x01, 0x02, 0x03, 0x81, 0x82 and 0x83, and Bitcoin Core 31.1 rejects a 65-byte signature ending in 00 with 'Invalid Schnorr signature hash type' and a 63-byte signature with 'Invalid Schnorr signature size' while accepting the 64-byte default and the explicit ALL (%s)." % WU, ["P05", "P20", "P24"]),
 ("F10", "Contemporary developments", "The book calls scriptless multisignatures an application of linearity that needs protection against key cancellation; the protection now exists as a standard: BIP327 (MuSig2) is Deployed, its key aggregation reproduces its four test vectors here, and a rogue key of the form 'my key minus yours' no longer gives the attacker control of the aggregate, while Bitcoin Core supports the musig() descriptor from version 30.0 and signing with it from version 31.0 (%s) (%s)." % (NI, BC), ["P07", "P14", "P27", "P45"]),
 ("F11", "Contemporary developments", "The book says no scriptless threshold signature protocol has been proposed as a BIP; the BIP index at the pinned commit still has no number for one, but Bitcoin Optech's topic page lists 'BIP proposed for creating FROST scriptless threshold signatures for Bitcoin' among its 2024 mentions and the FROST scheme itself was published in 2021, so the book's statement is a snapshot of 2023, and MuSig2 remains an n-of-n scheme and not a threshold scheme (%s) (%s)." % ("Bitcoin Optech, 2026", "Komlo and Goldberg, 2021"), ["P07", "P19", "P44", "P55"]),
 ("F12", "Contemporary developments", "The book names BIP118, SIGHASH_ANYPREVOUT, as a proposal; it is still a Draft in the BIP index and Bitcoin Core does not list it among the BIPs it implements, and Bitcoin Optech describes it as an updated version of SIGHASH_NOINPUT used by eltoo (%s) (%s)." % (DT, "Bitcoin Optech, 2026"), ["P11", "P19", "P45", "P56"]),
 ("F13", "Contemporary developments", "Bitcoin Core 30.0 made standard transactions with more than 2,500 potentially executed legacy signature operations non-standard, to prepare for BIP54, the consensus cleanup (Complete), which would make such a transaction invalid; the cap answers the long verification times of crafted legacy transactions of the kind CVE-2013-2292 named, and BIP54 states that its limit reduces the worst-case block validation time by a factor of 40, while CVE-2013-2292 is the earlier example of a transaction that takes minutes to verify (%s) (%s) (Bitcoin Wiki, 2026)." % (BC, "Poinsot and Corallo, 2025"), ["P15", "P25", "P29", "P51"]),
 ("F14", "Contemporary developments", "A Draft BIP 461 (2026) proposes deterministic ECDSA signatures with low-R grinding, so that signatures are at most 70 bytes when DER encoded instead of 72, and a Draft BIP 361 (2026) proposes a pre-announced sunset of legacy ECDSA and schnorr signatures as a migration to post-quantum signatures; both are proposals, neither is deployed, and the book has nothing on either (%s) (%s)." % ("Gilligan, 2026", "Lopp et al., 2026"), ["P16", "P17", "P58"]),
 ("F15", "Comparative analysis", "The book's statement that Schnorr's patent kept the algorithm out of open standards for almost two decades fits the dates: United States patent 4,995,082 was filed on 23 February 1990 and published on 19 February 1991, the statute gave a patent of that age the greater of 20 years from filing (23 February 2010) and 17 years from grant (19 February 2008), and Wikipedia says it expired in February 2010; the paper itself appeared in the proceedings of Crypto '89 (1990) and in the Journal of Cryptology in 1991 (%s) (%s)." % ("USPTO, 1991", "Cornell Legal Information Institute, 2026"), ["P37", "P38", "P47", "P48", "P49"]),
 ("F16", "Comparative analysis", "The book's identification protocol and the signature built from it by the Fiat-Shamir transform reproduce on secp256k1: with a fresh challenge the verifier's equation holds, with a changed response it fails, an impersonator who is told the challenge before committing can pass without the private key, and the signature with the challenge replaced by a hash of the commitment, key and message verifies for its message and fails for another, which is the construction of Fiat and Shamir (1986) and Schnorr (1991) (%s) (%s)." % ("Fiat and Shamir, 1986", "Schnorr, 1991"), ["P37", "P39", "P41"]),
 ("F17", "Comparative analysis", "The book's claim that schnorr signatures can be batch verified in about half the time of single verification rests on the linearity of the signature equation, which reproduces (the combined equation accepts the nine valid signatures of the BIP340 vectors and rejects the batch with one signature swapped), but the speed-up is not reproduced here because the libsecp256k1 README lists no batch verification API; BIP342 introduces OP_CHECKSIGADD precisely so that multisignature policies in tapscript stay batch verifiable (%s) (%s)." % (WU, "Bitcoin Core, 2026"), ["P03", "P06", "P33"]),
 ("F18", "Contemporary developments", "The 2013 weakness of the random number generator of Android, announced to Bitcoin users on 11 August 2013 and explained by the Android security team on 14 August, is the real-world case for the chapter's randomness section; the sources name the improper initialization of the generator but not the exact flaw that was exploited, while the chapter shows that two ECDSA signatures with one nonce give away the private key and that the deterministic nonce of RFC 6979 removes the need for a good generator at signing time (%s) (%s)." % ("Bitcoin.org, 2013", "Klyubin, 2013"), ["P34", "P59", "P60"]),
 ("F19", "Contemporary developments", "The libsecp256k1 library that Bitcoin Core uses for all of this removed the previously deprecated function alias secp256k1_schnorrsig_sign in version 0.8.0 (3 August 2026), and Bitcoin Core's key code calls secp256k1_schnorrsig_sign32; the book's description of schnorr signing is independent of that change but a reader of the library's header will meet the new name (%s)." % BC, ["P23", "P32"]),
 ("F20", "Conclusion", "For the course, a signature is the unit of authorization of a transaction, and the chapter's evidence shows how far it can be reproduced: every flag, every signature length, every encoding rule and the key recovery attack recompute from the standards and Bitcoin Core 31.1 on regtest, while the full security proof of ECDSA, the speed of batch verification, quantum attacks and the behaviour of other Core releases are not reproduced here (%s)." % A, ["P01"]),
]
